
    const state={user:null,csrf:'',alerts:[],alertsTotal:0,alertsOffset:0,decisions:[],decisionsTotal:0,decisionsOffset:0,logs:[],logsTotal:0,logsOffset:0,status:{},metrics:{},analytics:{},rules:[],notes:[],users:[]};
    const pageSize=100;let timer=null,filterTimer=null;
    const $=id=>document.getElementById(id),text=v=>v===undefined||v===null||v===''?'-':String(v),when=v=>v?new Date(v).toLocaleString('th-TH'):'-',escapeHtml=v=>text(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
    async function api(url,options={}){const res=await fetch(url,options);if(res.status===401&&state.user){showLogin()}const data=res.status===204?null:await res.json().catch(()=>({}));if(!res.ok){const error=new Error(data.detail||data.error||url+' '+res.status);error.status=res.status;error.data=data;throw error}return data}
    let loginChallenge='';
    async function finishLogin(data){loginChallenge='';$('login-totp-secret').value='';$('login-totp-enrollment').classList.add('hidden');state.user=data.user;state.csrf=data.csrf_token;$('password').value='';$('totp').value='';showApp();await refresh()}
    async function login(e){e.preventDefault();$('login-error').textContent='';try{const data=await api('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('username').value,password:$('password').value})});$('password').value='';if(data.totp_required){loginChallenge=data.challenge;$('login-totp-secret').value=data.enrollment_secret||'';$('login-totp-enrollment').classList.toggle('hidden',!data.enrollment_secret);$('login-form').classList.add('hidden');$('totp-login-form').classList.remove('hidden');$('totp').value='';$('totp-login-error').textContent='';$('totp').focus()}else{await finishLogin(data)}}catch(error){$('login-error').textContent=error.status===429?'ลองใหม่ภายหลัง: มีการเข้าสู่ระบบผิดหลายครั้ง':'Username หรือ Password ไม่ถูกต้อง'}}
    async function verifyLoginTotp(e){e.preventDefault();$('totp-login-error').textContent='';try{const data=await api('/api/login/totp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenge:loginChallenge,totp:$('totp').value})});await finishLogin(data)}catch(error){$('totp').value='';$('totp-login-error').textContent=error.status===429?'ลองใหม่ภายหลัง: กรอกรหัสผิดหลายครั้ง':'รหัสไม่ถูกต้อง ใช้แล้ว หรือหมดเวลา กรุณาลองรหัสใหม่หรือกลับไปเข้าสู่ระบบอีกครั้ง'}}
    function clearTotpSetup(){$('totp-setup-form').reset();$('totp-secret').value='';$('totp-enrollment').classList.add('hidden');$('totp-error').textContent=''}
    async function setupTotp(event,confirm=false){event.preventDefault();$('totp-error').textContent='';if(confirm&&!/^[0-9]{6}$/.test($('totp-confirm-code').value)){$('totp-error').textContent='กรุณากรอกรหัส TOTP 6 หลัก';return}try{const data=await api('/api/account/totp/'+(confirm?'confirm':'setup'),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify({current_password:$('totp-password').value,totp:$('totp-confirm-code').value})});if(confirm){clearTotpSetup();showLogin();$('login-error').textContent='เปิดใช้ TOTP แล้ว กรุณาเข้าสู่ระบบด้วยรหัสใหม่จาก Authenticator'}else{$('totp-secret').value=data.secret;$('totp-enrollment').classList.remove('hidden')}}catch(error){const messages={invalid_current_password:'รหัสผ่านปัจจุบันไม่ถูกต้อง',invalid_totp:'รหัส TOTP ไม่ถูกต้อง',totp_setup_expired:'หมดเวลาหรือกรอกผิดเกินกำหนด กรุณาตั้งค่าใหม่',totp_already_enabled:'บัญชีนี้เปิดใช้ TOTP แล้ว',rate_limited:'ลองใหม่ภายหลัง: กรอกผิดหลายครั้ง'};$('totp-error').textContent=messages[error.message]||error.message}}
    async function logout(){try{await api('/api/logout',{method:'POST',headers:{'X-CSRF-Token':state.csrf}})}finally{showLogin()}}
    function showLogin(){loginChallenge='';$('login-totp-secret').value='';$('login-totp-enrollment').classList.add('hidden');$('password').value='';$('totp').value='';$('login-form').classList.remove('hidden');$('totp-login-form').classList.add('hidden');clearTotpSetup();state.user=null;state.csrf='';state.users=[];$('issued-secret').textContent='';$('issued-password').classList.add('hidden');$('user-success').textContent='';$('app').classList.add('hidden');$('login-screen').classList.remove('hidden');if(timer)clearInterval(timer)}
    function showApp(){clearTotpSetup();$('totp-status').textContent=state.user.totp_enabled?'เปิดใช้ TOTP แล้ว':'ยังไม่ได้เปิดใช้ TOTP';$('totp-setup-form').classList.toggle('hidden',!!state.user.totp_enabled);$('login-screen').classList.add('hidden');$('app').classList.remove('hidden');$('user-name').textContent=state.user.name||state.user.username;$('account-username').textContent=state.user.username;$('user-role').textContent=state.user.role==='master_admin'?'Master Admin':'User';document.querySelectorAll('[data-admin]').forEach(el=>el.classList.toggle('hidden',state.user.role!=='master_admin'));selectAccountTab(state.user.role==='master_admin'?'users':'self');$('password-required-note').classList.toggle('hidden',!state.user.must_change_password);document.querySelector('nav').classList.toggle('hidden',!!state.user.must_change_password);document.querySelector('.toolbar').classList.toggle('hidden',!!state.user.must_change_password);selectRhTab('summary');if(state.user.must_change_password){selectAccountTab('self');switchView('account')}else{switchView('overview')}if(timer)clearInterval(timer);timer=setInterval(()=>$('auto-refresh').checked&&refresh(),10000)}
    function logQuery(){const params=new URLSearchParams({limit:pageSize,offset:state.logsOffset});for(const [id,key] of [['log-search','q'],['log-source','source'],['log-type','type'],['log-protocol','protocol'],['log-severity','severity']]){const value=$(id).value.trim();if(value)params.set(key,value)}for(const [id,key] of [['log-from','from'],['log-to','to']]){const value=$(id).value;if(value)params.set(key,new Date(value).toISOString())}return params}
    async function loadLogs(){const data=await api('/api/logs.json?'+logQuery());state.logs=data.items;state.logsTotal=data.total;renderLogs()}
    function renderBars(id,values,colors={}){const entries=Object.entries(values||{}).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...entries.map(([,v])=>v));$(id).innerHTML=entries.length?entries.map(([name,value])=>`<div class="bar-row"><span title="${escapeHtml(name)}">${escapeHtml(name)}</span><div class="bar-track"><div class="bar-fill ${colors[name]||''}" style="width:${Math.max(0,Math.min(100,Number(value)/max*100))}%"></div></div><strong>${value}</strong></div>`).join(''):'<div class="empty">ยังไม่มีข้อมูลในช่วงเวลานี้</div>'}
    function renderAnalytics(){const a=state.analytics,trend=a.trend||[];const max=Math.max(1,...trend.map(p=>p.count));$('trend-total').textContent=(a.total_alerts||0)+' เหตุการณ์';$('alert-trend').innerHTML=a.total_alerts?trend.map(p=>`<div class="chart-bar" style="height:${Math.max(2,p.count/max*100)}%" title="${escapeHtml(p.time)} UTC: ${p.count}"></div>`).join(''):'<div class="empty">ยังไม่มีเหตุการณ์ในช่วงเวลานี้</div>';$('alert-trend').setAttribute('aria-label',`แนวโน้ม ${a.total_alerts||0} เหตุการณ์`);$('trend-caption').innerHTML=trend.length&&a.total_alerts?`<span>${escapeHtml(trend[0].time)}</span><span>${escapeHtml(trend[trend.length-1].time)} UTC</span>`:'';renderBars('protocol-chart',a.protocols);renderBars('severity-chart',a.severities,{'1':'red-fill','2':'orange-fill'});renderBars('destination-chart',{real:(a.destinations||{}).real||0,honeypot:(a.destinations||{}).honeypot||0},{'honeypot':'violet-fill'})}
    function renderNotes(){const levels={critical:'วิกฤต',high:'สูง',warning:'เตือน',info:'ข้อมูล'};$('note-count').textContent=state.notes.length+' รายการ';$('notifications').innerHTML=state.notes.map(n=>`<div class="note"><strong><span class="pill ${noteClass(n.level)}">${escapeHtml(levels[n.level]||n.level)}</span> ${escapeHtml(n.title)}</strong><span>${escapeHtml(n.detail)}</span></div>`).join('')}
    function noteClass(l){return l==='critical'?'bad':l==='high'?'violet':l==='warning'?'warn':'info'}
    function renderLogs(){const start=state.logsTotal?state.logsOffset+1:0,end=Math.min(state.logsOffset+state.logs.length,state.logsTotal);$('logs-total').textContent=state.logsTotal.toLocaleString('th-TH');$('logs-count').textContent=`${start}-${end} จาก ${state.logsTotal}`;$('logs-prev').disabled=state.logsOffset===0;$('logs-next').disabled=end>=state.logsTotal;$('logs-body').innerHTML=state.logs.map(r=>`<tr><td class="mono log-time">${when(r.time)}</td><td><span class="log-type ${escapeHtml(r.type)}">${escapeHtml(logTypeLabels[r.type]||r.type)}</span></td><td class="mono log-ip">${escapeHtml(r.source)}</td><td>${escapeHtml(r.protocol)}</td><td>${r.severity?`<span class="pill ${severityClass(r.severity)}">ระดับ ${escapeHtml(r.severity)}</span>`:'—'}</td><td class="log-summary">${escapeHtml(r.summary)}</td><td><span class="pill ${r.type==='decision'?actionClass(r.result):'info'}">${escapeHtml(r.type==='rabbit_hole'?(actionText[r.result]||r.result):r.result)}</span></td></tr>`).join('')||'<tr><td colspan="7" class="empty">ไม่พบ Log ตามเงื่อนไข</td></tr>'}
    const logTypeLabels={suricata:'Suricata',decision:'Decision Engine',honeypot:'Honeypot',rabbit_hole:'Rabbit Hole'};
    function metric(v){return v===null||v===undefined?'N/A':Number(v).toFixed(1)+'ms'}
    function countBy(rows,key){return rows.reduce((a,r)=>{const k=r[key]||'unknown';a[k]=(a[k]||0)+1;return a},{})}function summaryBlock(title,data){const rows=Object.entries(data).map(([k,v])=>`<div class="service-row"><strong>${escapeHtml(k)}</strong><span>${v}</span></div>`).join('');return`<h4>${title}</h4>${rows||'<div class="empty">No data</div>'}`}
    function severityClass(v){return Number(v)===1?'bad':Number(v)===2?'warn':'info'}function ruleSeverityClass(v){return v==='high'?'bad':v==='medium'?'warn':'info'}function actionClass(v){v=String(v||'');return v.includes('redirect')?'violet':v==='monitor'?'warn':'ok'}
    function candidate(){return{rule_id:$('candidate-id').value.trim(),version:$('candidate-version').value.trim(),evidence:$('candidate-evidence').value.trim(),confidence:Number($('candidate-confidence').value),expected_sid:Number($('candidate-sid').value),rule:$('candidate-rule').value.trim()}}
    function clearCandidate(){['candidate-id','candidate-version','candidate-evidence','candidate-confidence','candidate-sid','candidate-rule'].forEach(id=>$(id).value='');$('candidate-result').className='pill info';$('candidate-result').textContent='Waiting for candidate'}
    async function loadUsers(){if(state.user.role!=='master_admin')return;const data=await api('/api/users.json');state.users=data.items;renderUsers()}
    function showIssued(title,password){$('issued-title').textContent=title;$('issued-secret').textContent=password;$('issued-password').classList.remove('hidden');$('issued-password').scrollIntoView({behavior:'smooth',block:'center'})}
    async function createUser(event){event.preventDefault();const password=$('initial-password').value,confirmation=$('initial-password-confirm').value;$('user-error').textContent='';$('user-success').textContent='';$('issued-password').classList.add('hidden');$('issued-secret').textContent='';if(password!==confirmation){$('user-error').textContent='ยืนยันรหัสผ่านเริ่มต้นไม่ตรงกัน';return}try{const data=await api('/api/users',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify({username:$('new-username').value.trim(),name:$('new-name').value.trim(),password})});$('create-user-form').reset();if(data.temporary_password)showIssued('รหัสผ่านเริ่มต้นของ '+data.user.username,data.temporary_password);else $('user-success').textContent='สร้างบัญชี '+data.user.username+' แล้ว กรุณาส่งรหัสผ่านที่ตั้งไว้ให้ผู้ใช้';await loadUsers()}catch(error){$('user-error').textContent=error.status===409?'Username นี้มีอยู่แล้ว':error.status===503?'ที่เก็บบัญชีไม่พร้อมให้เขียน':error.message==='invalid_password'?'รหัสผ่านต้องมี 12–128 ตัวอักษร':error.message}}
    async function changePassword(event){event.preventDefault();const current=$('current-password').value,next=$('new-password').value;if(next!==$('confirm-password').value){$('password-error').textContent='รหัสผ่านใหม่ไม่ตรงกัน';return}$('password-error').textContent='';try{await api('/api/account/password',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify({current_password:current,new_password:next})});$('password-form').reset();showLogin();$('login-error').textContent='เปลี่ยนรหัสผ่านแล้ว กรุณาเข้าสู่ระบบอีกครั้ง'}catch(error){$('password-error').textContent=error.message==='invalid_current_password'?'รหัสผ่านปัจจุบันไม่ถูกต้อง':error.message==='password_unchanged'?'กรุณาใช้รหัสผ่านใหม่':error.message}}
    function selectAccountTab(id){if(state.user.role!=='master_admin')id='self';$('issued-secret').textContent='';$('issued-password').classList.add('hidden');for(const button of document.querySelectorAll('.account-tab')){const selected=button.dataset.accountTab===id;button.classList.toggle('active',selected);button.setAttribute('aria-selected',String(selected))}for(const panel of document.querySelectorAll('.account-panel'))panel.classList.toggle('hidden',panel.id!=='account-'+id)}
    function switchView(id){if(id!=='account'){$('issued-secret').textContent='';$('issued-password').classList.add('hidden');$('user-success').textContent=''}document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===id));$('view-title').textContent=document.querySelector(`[data-view="${id}"]`).textContent}
    const actionLabels={allow:'ส่งไปบริการจริง',monitor:'เฝ้าระวัง / บริการจริง',redirect_web:'ส่งต่อ Web Honeypot',redirect_ssh:'ส่งต่อ SSH Honeypot',redirect_telnet:'ส่งต่อ Telnet Honeypot'};
    let eventsOffset=0,eventsData={items:[],total:0,unread:0}, capabilities={},candidateItems=[];
    const duration=v=>v===null||v===undefined?'ยังไม่มีข้อมูล':Number(v)<60?Number(v).toFixed(1)+' วินาที':(Number(v)/60).toFixed(1)+' นาที';
    async function postScope(url,payload){return api(url,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify(payload)})}
    async function loadEvents(){eventsData=await api('/api/events.json?'+new URLSearchParams({limit:25,offset:eventsOffset,status:$('events-status').value,order:$('events-order').value}));renderEvents()}
    function renderEvents(){const start=eventsData.total?eventsOffset+1:0,end=Math.min(eventsOffset+eventsData.items.length,eventsData.total);$('events-count').textContent=`${start}–${end} / ${eventsData.total}`;$('events-unread').textContent=eventsData.unread.toLocaleString('th-TH')+' ยังไม่อ่าน';$('events-prev').disabled=eventsOffset===0;$('events-next').disabled=end>=eventsData.total;$('events-body').innerHTML=eventsData.items.map(r=>`<tr class="${r.read?'':'unread-row'}"><td>${when(r.timestamp)}</td><td class="mono">${escapeHtml(r.source_ip)}</td><td><span class="pill ${actionClass(r.action)}">${escapeHtml(actionLabels[r.action]||r.action)}</span><small>${escapeHtml(r.profile)}</small></td><td><strong>${escapeHtml(r.rule_name||'SID '+r.signature_id)}</strong><small>${escapeHtml(r.reason)}</small></td><td><span class="pill ${severityClass(r.severity)}">${escapeHtml(r.severity)}</span></td><td>${duration(r.dwell_seconds)}</td><td><span class="pill ${r.read?'ok':'warn'}">${r.read?'อ่านแล้ว':'ยังไม่อ่าน'}</span><div class="split-actions"><button class="tonal small event-action" data-id="${escapeHtml(r.id)}" data-action="${r.read?'unread':'read'}">${r.read?'ทำเป็นยังไม่อ่าน':'อ่านแล้ว'}</button><button class="danger small event-action" data-id="${escapeHtml(r.id)}" data-action="deleted">ลบ</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">ไม่มีการแจ้งเตือนตามเงื่อนไข</td></tr>'}
    async function refresh(){if(state.user?.must_change_password)return;try{const common=await Promise.all([api('/api/status.json'),api('/api/analytics.json?window='+encodeURIComponent($('analytics-window').value)),api('/api/notifications.json'),api('/api/capabilities.json'),loadLogs(),loadEvents()]);state.status=common[0];state.analytics=common[1];state.notes=common[2];capabilities=common[3];await loadRabbit();if(state.user.role==='master_admin'){const extra=await Promise.all([api('/api/rules.json'),api('/api/thresholds.json'),api('/api/rule-backups.json'),api('/api/candidates.json')]);state.rules=extra[0];$('threshold-monitor').value=extra[1].monitor;$('threshold-redirect').value=extra[1].redirect;$('rule-backups').innerHTML=extra[2].items.map(b=>`<option value="${escapeHtml(b.id)}">${escapeHtml(b.id)}</option>`).join('');candidateItems=extra[3].items;renderCandidates()}renderAll()}catch(error){if(error.status!==401)$('last-updated').textContent='รีเฟรชไม่สำเร็จ: '+error.message}}
    function renderAll(){$('last-updated').textContent='อัปเดตล่าสุด: '+new Date().toLocaleTimeString('th-TH');$('stat-alerts').textContent=(state.analytics.total_alerts||0).toLocaleString('th-TH');$('stat-sources').textContent=(state.analytics.unique_source_ips||0).toLocaleString('th-TH');$('stat-redirects').textContent=((state.analytics.destinations||{}).honeypot||0).toLocaleString('th-TH');$('stat-high').textContent=(state.analytics.high_severity_alerts||0).toLocaleString('th-TH');renderAnalytics();renderServices();renderNotes();renderLogs();renderRules();renderReports();renderRabbit();renderRank();$('honeypot-availability').textContent=state.analytics.honeypot_telemetry_available?'เวลาใน Honeypot คำนวณจาก Action แรกถึง Action สุดท้ายของแต่ละ Session':'ยังไม่มีข้อมูล Action จาก Honeypot ในช่วงเวลานี้';$('rule-mode').textContent=capabilities.rule_edit_available?'จัดการชุดกฎใน Dashboard':'การแก้กฎบนเครื่องจริงต้องเชื่อม Deployment Helper';$('rule-save').disabled=!capabilities.rule_edit_available;$('rule-restore').disabled=!capabilities.rule_edit_available}
    function renderRank(){const rows=state.analytics.severity_rank||[];$('stat-high-pill').textContent=(state.analytics.high_severity_alerts||0).toLocaleString('th-TH')+' เหตุการณ์';const max=Math.max(1,...rows.map(r=>r.count));$('severity-rank').innerHTML=rows.length?`<ol class="rank">${rows.map((r,i)=>`<li><span class="rank-no">${i+1}</span><span class="mono">${escapeHtml(r.source_ip)}</span><span class="bar-track"><span class="bar-fill red-fill" style="width:${r.count/max*100}%"></span></span><strong>${r.count.toLocaleString('th-TH')}</strong></li>`).join('')}</ol>`:'<div class="empty">ไม่มีเหตุการณ์ความรุนแรงสูงในช่วงเวลานี้</div>'}
    function renderServices(){const labels={active:'ทำงาน',inactive:'หยุดทำงาน',unavailable:'ตรวจสอบไม่ได้','not-found':'ไม่พบบริการ',unknown:'ไม่ทราบสถานะ'},names={suricata:'Suricata',nginx:'Nginx',decision_engine:'Decision Engine'};$('services').innerHTML=Object.entries(names).map(([key,name])=>{const value=state.status[key]||(key==='decision_engine'?state.status['adaptive-defender']:null)||'unknown';return `<div class="service-row"><strong>${name}</strong><span class="pill ${value==='active'?'ok':value==='unknown'?'info':'warn'}">${escapeHtml(labels[value]||value)}</span></div>`}).join('')}
    function renderReports(){const a=state.analytics;$('report-high').textContent=(a.total_decisions||0).toLocaleString('th-TH');$('report-redirects').textContent=(a.destinations||{}).honeypot||0;$('report-real').textContent=(a.destinations||{}).real||0;$('report-sessions').textContent=a.honeypot_sessions||0;$('report-export').href='/api/reports.csv?window='+encodeURIComponent($('analytics-window').value);$('report-summary').innerHTML=`<div class="grid two"><div>${summaryBlock('เหตุการณ์ Decision Engine แยกตามโปรโตคอล',a.decision_protocols||{})}</div><div>${summaryBlock('เหตุการณ์ Decision Engine แยกตามความรุนแรง',a.decision_severities||{})}</div></div>`;renderReportRabbit(a.rabbit_hole);$('dwell-body').innerHTML=(a.honeypot_dwell||[]).map(s=>`<tr><td>${escapeHtml(s.profile)}</td><td>${s.sessions}</td><td>${duration(s.average_seconds)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">ไม่มีข้อมูล Honeypot ในช่วงเวลานี้</td></tr>'}
    function renderRules(){if(state.user.role!=='master_admin')return;$('rules-count').textContent=state.rules.length+' กฎ';$('rules-body').innerHTML=state.rules.map(r=>`<tr><td class="mono">${r.sid}</td><td><span class="pill ${ruleSeverityClass(r.severity)}">${escapeHtml(r.severity)}</span></td><td>${escapeHtml(r.message)}<small>${escapeHtml(r.classtype)}</small></td><td><span class="pill ${r.enabled?'ok':'warn'}">${r.enabled?'เปิด':'ปิด'}</span></td><td><div class="split-actions"><button class="secondary small rule-action" data-action="edit" data-sid="${r.sid}">แก้ไข</button><button class="text small rule-action" data-action="toggle" data-sid="${r.sid}" ${capabilities.rule_edit_available?'':'disabled'}>${r.enabled?'ปิด':'เปิด'}</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">ยังไม่มีกฎ</td></tr>'}
    function renderCandidates(){$('candidate-queue').innerHTML=candidateItems.map(c=>`<div class="note"><strong>${escapeHtml(c.rule_id)} · SID ${c.expected_sid}</strong><span>หลักฐาน: ${escapeHtml(c.evidence)}</span><pre>${escapeHtml(c.rule)}</pre><span>${c.test_results.gates.map(g=>escapeHtml(g.name)+': '+escapeHtml(g.status)).join(' · ')}</span><span class="pill ${c.status==='approved'?'ok':'warn'}">${c.status==='approved'?'อนุมัติแล้ว':'รออนุมัติ'}</span>${c.status==='pending'?`<button class="small approve-candidate" data-id="${escapeHtml(c.rule_id)}" ${capabilities.rule_edit_available?'':'disabled'}>อนุมัติและเพิ่มกฎ</button>`:''}</div>`).join('')||'<div class="empty">ยังไม่มีกฎเสนอให้ตรวจสอบ</div>'}
    async function ruleAction(action){const result=$('candidate-result');result.className='pill info';result.textContent='กำลังตรวจสอบ…';try{const data=action==='validate'?await postScope('/api/rules/validate',candidate()):await postScope('/api/candidates/save',candidate());result.className='pill ok';result.textContent=action==='validate'?`ผ่าน ${data.gates.length} ขั้นตอน (ชุดทดสอบ Baseline)`:'บันทึกเข้าคิวรออนุมัติแล้ว';await refresh()}catch(error){result.className='pill bad';result.textContent=error.message}}
    function renderUsers(){$('users-count').textContent=state.users.length+' บัญชี';$('users-body').innerHTML=state.users.map(u=>`<tr><td class="mono">${escapeHtml(u.username)}</td><td>${escapeHtml(u.name)}</td><td>${u.role==='master_admin'?'Master Admin':'User'}</td><td><span class="pill ${u.disabled?'warn':'ok'}">${u.disabled?'ระงับ':'ใช้งาน'}</span></td><td><div class="split-actions"><button class="secondary small user-action" data-action="edit" data-username="${escapeHtml(u.username)}">แก้ไข / สิทธิ์</button><button class="danger small user-action" data-action="delete" data-username="${escapeHtml(u.username)}" ${u.username===state.user.username?'disabled':''}>ลบ</button>${u.role==='user'?`<button class="text small user-action" data-action="status" data-username="${escapeHtml(u.username)}">${u.disabled?'เปิดใช้':'ระงับ'}</button><button class="text small user-action" data-action="reset" data-username="${escapeHtml(u.username)}">รีเซ็ตรหัส</button>`:''}</div></td></tr>`).join('')}
    async function manageUser(event){const button=event.target.closest('.user-action');if(!button)return;const username=button.dataset.username,action=button.dataset.action,account=state.users.find(u=>u.username===username);if(action==='edit'){$('edit-username').value=username;$('edit-name').value=account.name;$('edit-role').value=account.role;$('user-edit-error').textContent='';$('user-edit-dialog').showModal();return}if(!confirm(action==='delete'?`ลบบัญชี ${username}?`:`ดำเนินการ ${action} กับ ${username}?`))return;try{const endpoint=action==='reset'?'reset-password':action;const data=await postScope('/api/users/'+encodeURIComponent(username)+'/'+endpoint,action==='status'?{disabled:!account.disabled}:{});if(action==='reset')showIssued('รหัสผ่านใหม่ของ '+username,data.temporary_password);await loadUsers()}catch(error){$('users-error').textContent=error.message}}
    async function scopeEvents(event){const button=event.target.closest('.event-action');if(!button)return;if(button.dataset.action==='deleted'&&!confirm('ลบข้อความแจ้งเตือนนี้?'))return;try{await postScope('/api/events/update',{id:button.dataset.id,action:button.dataset.action});await loadEvents()}catch(error){$('events-error').textContent=error.message}}
    $('events-body').addEventListener('click',scopeEvents);
