    $('threshold-form').addEventListener('submit',async event=>{event.preventDefault();try{await postScope('/api/thresholds',{monitor:Number($('threshold-monitor').value),redirect:Number($('threshold-redirect').value)});$('threshold-result').textContent='บันทึกแล้ว ใช้กับเหตุการณ์ใหม่เมื่อ Decision Engine อ่าน config รอบถัดไป'}catch(error){$('threshold-result').textContent=error.message}});
    $('rule-new').addEventListener('click',()=>{$('rule-sid').value='';$('rule-text').value='';$('rule-editor-title').textContent='เพิ่มกฎใหม่';$('rule-error').textContent=''});
    $('rules-body').addEventListener('click',async event=>{const button=event.target.closest('.rule-action');if(!button)return;const rule=state.rules.find(r=>r.sid===Number(button.dataset.sid));if(button.dataset.action==='edit'){$('rule-sid').value=rule.sid;$('rule-text').value=rule.rule;$('rule-editor-title').textContent='แก้ไข SID '+rule.sid;return}try{await postScope('/api/rules/change',{action:'toggle',sid:rule.sid,enabled:!rule.enabled});await refresh()}catch(error){$('rule-error').textContent=error.message}});
    $('rule-editor-form').addEventListener('submit',async event=>{event.preventDefault();try{await postScope('/api/rules/change',{action:$('rule-sid').value?'edit':'add',sid:Number($('rule-sid').value),rule:$('rule-text').value.trim()});$('rule-error').textContent='บันทึกและสำรองกฎเดิมแล้ว';await refresh()}catch(error){$('rule-error').textContent=error.message}});
    $('rule-restore').addEventListener('click',async()=>{if(!$('rule-backups').value||!confirm('คืนค่ากฎจากชุดสำรองที่เลือก?'))return;try{await postScope('/api/rules/change',{action:'restore',backup:$('rule-backups').value});await refresh()}catch(error){$('rule-error').textContent=error.message}});
    $('candidate-queue').addEventListener('click',async event=>{const button=event.target.closest('.approve-candidate');if(!button||!confirm('อนุมัติและเพิ่มกฎนี้?'))return;try{await postScope('/api/candidates/approve',{rule_id:button.dataset.id});await refresh()}catch(error){$('candidate-result').textContent=error.message}});
    $('user-edit-form').addEventListener('submit',async event=>{event.preventDefault();try{await postScope('/api/users/'+encodeURIComponent($('edit-username').value)+'/edit',{name:$('edit-name').value,role:$('edit-role').value});$('user-edit-dialog').close();if($('edit-username').value===state.user.username){showLogin();return}await loadUsers()}catch(error){$('user-edit-error').textContent=error.message}});
    $('user-edit-cancel').addEventListener('click',()=>$('user-edit-dialog').close());
    $('logs-flush').addEventListener('click',()=>{$('flush-form').reset();$('flush-error').textContent='';$('flush-dialog').showModal()});
    $('flush-cancel').addEventListener('click',()=>$('flush-dialog').close());
    $('flush-form').addEventListener('submit',async event=>{event.preventDefault();try{await postScope('/api/logs/flush',{confirmation:$('flush-confirmation').value,totp:$('flush-totp').value});$('flush-dialog').close();eventsOffset=0;state.logsOffset=0;await refresh()}catch(error){$('flush-error').textContent=error.message==='flush_totp_required'?'ต้องตั้งค่า Authenticator ในบัญชีของฉัน แล้วกรอกรหัส TOTP ที่ยังไม่ใช้ พร้อมพิมพ์ FLUSH':error.message}});

    document.querySelectorAll('.nav-btn').forEach(b=>b.addEventListener('click',()=>{switchView(b.dataset.view);if(b.dataset.view==='account'&&state.user.role==='master_admin')loadUsers().catch(error=>$('users-error').textContent=error.message)}));
    document.querySelectorAll('.account-tab').forEach(b=>b.addEventListener('click',()=>selectAccountTab(b.dataset.accountTab)));
    $('create-user-form').addEventListener('submit',createUser);
