    $('analytics-window').addEventListener('change',refresh);
    ['log-search','log-source','log-type','log-protocol','log-severity','log-from','log-to'].forEach(id=>$(id).addEventListener('input',()=>{clearTimeout(filterTimer);filterTimer=setTimeout(()=>{state.logsOffset=0;$('logs-error').textContent='';loadLogs().catch(error=>$('logs-error').textContent=error.message)},250)}));
    $('logs-clear').addEventListener('click',()=>{['log-search','log-source','log-type','log-protocol','log-severity','log-from','log-to'].forEach(id=>$(id).value='');state.logsOffset=0;$('logs-error').textContent='';loadLogs().catch(error=>$('logs-error').textContent=error.message)});
