    api('/api/session.json').then(data=>{if(data.session){state.user=data.session.user;state.csrf=data.session.csrf_token;showApp();refresh()}}).catch(()=>{});

    /* ---------- Rabbit Hole ---------- */
    const rh={data:null,selected:null,available:true};
    const endLabels={idle_timeout:'ไม่มีกิจกรรมเกิน Idle Timeout',session_closed:'ปิดการเชื่อมต่อ',limit_reached:'ถึงขอบเขตที่กำหนด',active:'ยังมีกิจกรรมอยู่'};
    const actionText={read_file:'อ่านไฟล์',list_directory:'เปิดรายการไฟล์',call_api:'เรียก API',call_api_denied:'เรียก API แต่ไม่มี Key ที่ถูกต้อง',open_page:'เปิดหน้าเว็บ',submit_form:'ส่งฟอร์มเข้าสู่ระบบ',read_attempt:'พิมพ์คำสั่งอ่านไฟล์',list_attempt:'พิมพ์คำสั่งดูรายการ',change_directory:'เข้าโฟลเดอร์'};
    const protoName=v=>({web:'Web',http:'Web',https:'Web',ssh:'SSH',telnet:'Telnet'}[String(v||'').toLowerCase()]||text(v));
    const shortWhen=v=>v?new Date(v).toLocaleString('th-TH',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'-';
    const pct=v=>v===null||v===undefined?'-':Math.round(v*100)+'%';
    const secs=v=>v===null||v===undefined?'-':duration(v);
    async function loadRabbit(){if(!rh.available)return;try{rh.data=await api('/api/rabbit-hole.json?window='+encodeURIComponent($('analytics-window').value));$('rh-error').textContent=''}catch(error){rh.data=null;if(error.status===404){rh.available=false}else{$('rh-error').textContent='โหลดข้อมูล Rabbit Hole ไม่สำเร็จ: '+error.message}}}
    function pips(depth){return `<span class="depth-pips" aria-label="ความลึก ${depth} ชั้น">${[1,2,3,4,5].map(i=>`<i class="${i<=depth?'on':''}"></i>`).join('')}</span>`}
    function strata(target,dist,total){const counts=[1,2,3,4,5].map(d=>Object.entries(dist||{}).filter(([k])=>Number(k)>=d).reduce((a,[,v])=>a+v,0));const base=Math.max(1,counts[0]);$(target).innerHTML=total?counts.map((c,i)=>`<div class="stratum"><span class="depth-name">ชั้น ${i+1}</span><span class="reach"><i style="width:${c/base*100}%"></i></span><span class="reach-value">${c.toLocaleString('th-TH')}<small>${Math.round(c/base*100)}%</small></span></div>`).join(''):'<div class="empty">ยังไม่มีผู้โจมตีเข้าเส้นทางลวงในช่วงเวลานี้</div>'}
    function tunnel(dist,total){const counts=[1,2,3,4,5].map(d=>Object.entries(dist||{}).filter(([k])=>Number(k)>=d).reduce((a,[,v])=>a+v,0));const base=Math.max(1,counts[0]);$('rh-tunnel').innerHTML=total?counts.map((c,i)=>`<div class="ring" style="--i:${i};--reach:${(c/base).toFixed(3)}"><span>ชั้น ${i+1} · ${c.toLocaleString('th-TH')}</span></div>`).join('')+`<div class="core"><b>${counts[4].toLocaleString('th-TH')}</b><small>ไปถึงชั้นลึกสุด</small></div>`:'<div class="core"><b>0</b><small>ยังไม่มีใครเข้าเส้นทางลวง</small></div>'}
    function figures(o){return [['Session ที่เข้าเส้นทางลวง',(o.sessions||0).toLocaleString('th-TH'),`${o.windows||0} ช่วงการติดตาม`],['เดินตามเบาะแสอย่างน้อย 1 ขั้น',pct(o.follow_rate),`${o.sessions_followed||0} Session`],['ความลึกเฉลี่ย',o.average_depth??'-',`ลึกสุด ${o.max_depth||0} ชั้น`],['เวลาโต้ตอบเฉลี่ย',secs(o.average_duration_seconds),`มัธยฐาน ${secs(o.median_duration_seconds)}`]].map(([l,v,h])=>`<div class="figure"><span>${l}</span><b>${v}</b><small>${h}</small></div>`).join('')}
    function renderRabbit(){const card=$('overview-rabbit');if(!rh.available||!rh.data){card.classList.add('hidden');$('rh-state').textContent=rh.available?'-':'ยังไม่ได้ตั้งค่า';return}card.classList.remove('hidden');const d=rh.data,o=d.summary.overall;$('rh-state').className='pill '+(d.enabled?'ok':'warn');$('rh-state').textContent=d.enabled?'เปิดใช้งาน':'ปิดอยู่';strata('overview-strata',d.summary.depth_distribution,o.windows);$('overview-rabbit-figures').innerHTML=`<div class="service-row"><strong>Session ที่เข้าเส้นทางลวง</strong><span>${o.sessions}</span></div><div class="service-row"><strong>เดินตามเบาะแส</strong><span>${pct(o.follow_rate)}</span></div><div class="service-row"><strong>ความลึกเฉลี่ย</strong><span>${o.average_depth??'-'} ชั้น</span></div><div class="service-row"><strong>เวลาโต้ตอบเฉลี่ย</strong><span>${secs(o.average_duration_seconds)}</span></div>`;$('rh-figures').innerHTML=figures(o);tunnel(d.summary.depth_distribution,o.windows);strata('rh-strata',d.summary.depth_distribution,o.windows);const c=d.summary.comparison,max=Math.max(1,c.static_average_seconds||0,c.rabbit_average_seconds||0);$('rh-compare').innerHTML=[['Honeypot แบบคงที่',c.static_average_seconds,''],['Rabbit Hole',c.rabbit_average_seconds,'violet-fill']].map(([n,v,cls])=>`<div class="compare-row"><span>${n}</span><div class="bar-track"><div class="bar-fill ${cls}" style="width:${(v||0)/max*100}%"></div></div><strong>${secs(v)}</strong></div>`).join('');$('rh-compare-note').textContent=`เวลาเฉลี่ยต่อ Session ที่มีมากกว่า 1 กิจกรรม (Honeypot แบบคงที่ ${c.static_sessions} Session) · ${c.note}`;$('rh-protocols').innerHTML=Object.entries(d.summary.by_protocol).map(([k,b])=>`<tr><td>${protoName(k)}</td><td>${b.sessions}</td><td>${pct(b.follow_rate)}</td><td>${b.average_depth??'-'} / ${b.max_depth}</td><td>${secs(b.average_duration_seconds)}</td><td>${k==='web'?'—':secs(b.average_connection_seconds)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">ยังไม่มีข้อมูล</td></tr>';const names={};d.scenarios.forEach(s=>s.nodes.forEach(n=>names[s.id+'/'+n.id]=n.path));renderBars('rh-resources',Object.fromEntries(d.summary.top_resources.map(r=>[names[r.scenario+'/'+r.node_id]||r.node_id,r.count])),Object.fromEntries(d.summary.top_resources.map(r=>[names[r.scenario+'/'+r.node_id]||r.node_id,'violet-fill'])));renderWindows();if(state.user.role==='master_admin')renderSetup()}
    function filteredWindows(){if(!rh.data)return[];const p=$('rh-filter-protocol').value,dep=Number($('rh-filter-depth').value),f=$('rh-filter-followed').checked;return rh.data.windows.filter(w=>(!p||(p==='web'?w.family==='web':w.protocol===p))&&w.max_depth>=dep&&(!f||w.followed))}
    function renderWindows(){const rows=filteredWindows();$('rh-window-count').textContent=`${rows.length} จาก ${rh.data.total_windows} ช่วงการติดตาม`;$('rh-windows-body').innerHTML=rows.map(w=>`<tr tabindex="0" data-id="${escapeHtml(w.id)}" class="${w.id===rh.selected?'selected':''}"><td class="mono">${shortWhen(w.start)}</td><td class="mono">${escapeHtml(w.source_ip)}</td><td>${protoName(w.family==='web'?'web':w.protocol)}</td><td>${pips(w.max_depth)}</td><td>${w.resources} / ${w.clues_followed}</td><td>${w.single_access?'ครั้งเดียว':secs(w.duration_seconds)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">ไม่มี Session ตามเงื่อนไข</td></tr>'}
    async function showTrail(id){rh.selected=id;renderWindows();$('rh-trail').innerHTML='<div class="empty">กำลังโหลด…</div>';try{const w=await api('/api/rabbit-hole/window.json?id='+encodeURIComponent(id));const start=new Date(w.start).getTime();const offset=t=>{const s=Math.round((new Date(t).getTime()-start)/1000);return '+'+String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')};const links={cookie:'Cookie',ip_ua:'IP + User-Agent (เชื่อมโยงแบบหลวม)',api_key:'API Key ที่ได้จากเบาะแส',cowrie_session:'Session ของ Cowrie'};$('rh-trail').innerHTML=`<div class="trail"><div class="trail-meta"><span><b>${escapeHtml(w.source_ip)}</b> · ${protoName(w.family==='web'?'web':w.protocol)}</span><span>ลึก <b>${w.max_depth}</b> ชั้น</span><span>เวลาโต้ตอบ <b>${w.single_access?'เข้าถึงครั้งเดียว':secs(w.duration_seconds)}</b></span>${w.connection_seconds!=null?`<span>เชื่อมต่อ <b>${secs(w.connection_seconds)}</b></span>`:''}<span>สิ้นสุดเพราะ <b>${escapeHtml(endLabels[w.end_reason]||w.end_reason)}</b></span><span>เชื่อม Session ด้วย ${w.links.map(l=>escapeHtml(links[l]||l)).join(', ')}</span></div>${w.trail.map(s=>`<div class="step" data-depth="${Math.min(5,s.depth||1)}" style="--depth:${Math.min(5,s.depth||1)}"><div class="step-top"><span class="step-time">${offset(s.time)}</span><span class="step-path">${escapeHtml(s.path)}</span><span class="pill deep">ชั้น ${s.depth}</span></div><div class="step-why ${s.followed_clue?'followed':''}">${escapeHtml(actionText[s.action]||s.action)}${s.followed_clue?' · ตามเบาะแสจาก '+escapeHtml(s.clue_from):s.clue_from?' · เห็นชื่อจาก '+escapeHtml(s.clue_from):' · เข้าตรงโดยไม่ผ่านเบาะแส'}</div></div>`).join('')}${w.user_agent?`<p class="data-note">User-Agent: ${escapeHtml(w.user_agent)}</p>`:''}</div>`}catch(error){$('rh-trail').innerHTML=`<p class="error">${escapeHtml(error.message)}</p>`}}
    function selectRhTab(id){if(id==='setup'&&state.user?.role!=='master_admin')id='summary';document.querySelectorAll('[data-rh-tab]').forEach(b=>{const on=b.dataset.rhTab===id;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on))});['summary','sessions','setup'].forEach(k=>$('rh-'+k).classList.toggle('hidden',k!==id))}
    let setupFilled=false;
    function renderSetup(){const d=rh.data,s=d.settings;if(!setupFilled){$('rh-enabled').checked=s.enabled;Object.entries(s.organization).forEach(([k,v])=>{if($('rh-org-'+k))$('rh-org-'+k).value=v});Object.entries(s.limits).forEach(([k,v])=>{if($('rh-limit-'+k))$('rh-limit-'+k).value=v})}$('rh-settings-result').innerHTML=d.problems.length?`<span class="problems">ต้องแก้ก่อนใช้งาน: ${d.problems.map(escapeHtml).join(' · ')}</span>`:'';if(setupFilled)return;renderLibrary();setupFilled=true}
    const kindNames={file:'ไฟล์',listing:'โฟลเดอร์ (รายการไฟล์)',api:'API (JSON)',form:'หน้า Login',people_api:'API รายชื่อคน',dir:'โฟลเดอร์'};
    function nodeMap(nodes,orphansFirst){const by={};nodes.forEach(x=>(by[x.depth||0]=by[x.depth||0]||[]).push(x));return Object.keys(by).map(Number).sort((a,b)=>orphansFirst?a-b:(a||99)-(b||99)).map(k=>`<div class="node-col ${k?'':'orphans'}"><h5>${k?'ชั้น '+k:'ยังไม่มีทางเข้า'}</h5>${by[k].map(x=>`<div class="node ${x.entry?'entry':''}"><code>${escapeHtml(x.path)}</code><small>${escapeHtml(kindNames[x.kind]||x.kind)}${x.next.length?' · ชี้ไป '+x.next.length+' จุด':''}${x.entry?' · จุดเริ่ม':''}</small></div>`).join('')}</div>`).join('')}
    function renderLibrary(){const list=rh.data.scenarios;const card=sc=>`<div class="scenario"><div class="scenario-head"><div class="scenario-info"><div class="scenario-title"><h4 class="card-title">${escapeHtml(sc.title)}</h4><span class="pill ${sc.builtin?'info':'ok'}">${sc.builtin?'เทมเพลต':'ฉากของฉัน'}</span><span class="pill">${sc.protocol==='shell'?'SSH/Telnet':'Web'}</span></div><p>${escapeHtml(sc.description)}</p></div><div class="scenario-actions"><label class="use-toggle"><input type="${sc.protocol==='shell'?'radio':'checkbox'}" name="rh-scn-${sc.protocol}" value="${escapeHtml(sc.id)}" data-protocol="${sc.protocol}" ${sc.selected?'checked':''}> ใช้ฉากนี้</label><button type="button" class="text small rh-preview" data-id="${escapeHtml(sc.id)}">ดูสิ่งที่ผู้โจมตีเห็น</button>${sc.builtin?`<button type="button" class="tonal small rh-copy" data-id="${escapeHtml(sc.id)}">ใช้เป็นต้นแบบ</button>`:`<button type="button" class="danger small rh-delete" data-id="${escapeHtml(sc.id)}">ลบ</button><button type="button" class="tonal small rh-edit" data-id="${escapeHtml(sc.id)}">แก้ไข</button>`}</div></div><div class="node-map">${nodeMap(sc.nodes)}</div></div>`;const mine=list.filter(s=>!s.builtin),tpl=list.filter(s=>s.builtin);$('rh-scenarios').innerHTML=(mine.length?`<h4 class="sub-title">ฉากของฉัน</h4>${mine.map(card).join('')}`:'<div class="empty-box">ยังไม่มีฉากที่สร้างเอง เริ่มจากกด "ใช้เป็นต้นแบบ" ที่เทมเพลตด้านล่าง หรือกด "+ สร้างฉาก"</div>')+`<h4 class="sub-title">เทมเพลต</h4>${tpl.map(card).join('')}`}

    /* ---------- scenario editor ---------- */
    const ed={def:null,sel:null,report:{errors:[],warnings:[]},timer:null,dirty:false,isNew:false};
    const insertables=[['ชื่อองค์กร','{{org.name}}'],['ชื่อย่อ','{{org.short_name}}'],['โดเมน','{{org.domain}}'],['ชื่อเซิร์ฟเวอร์','{{org.hostname}}'],['บัญชีผู้ดูแล','{{org.admin_user}}'],['ชื่อฐานข้อมูล','{{org.db_name}}'],['วันที่ (วันนี้)','{{date}}'],['วันที่ 7 วันก่อน','{{date:-7}}'],['IP ภายใน','{{ip:db}}'],['รหัสผ่านสุ่ม','{{secret:password:LABEL}}'],['API Key สุ่ม','{{secret:token:api}}'],['รหัส hex สุ่ม','{{secret:hex:12:LABEL}}'],['ชื่อคน','{{person:1:name}}'],['อีเมลคน','{{person:1:email}}'],['ตาราง CSV รายชื่อ 20 คน','{{people_csv:20}}'],['JSON รายชื่อ 10 คน','{{people_json:10}}']];
    const slug=v=>String(v||'').split('/').filter(Boolean).pop()?.replace(/\{\{[^}]*\}\}/g,'x').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,40)||'node';
    function uniqueId(base){const used=new Set(ed.def.nodes.map(n=>n.id));let id=/^[a-z0-9]/.test(base)?base:'n-'+base,i=2;while(used.has(id))id=base+'-'+i++;return id}
    function depths(){const d={},q=[];ed.def.entry.forEach(id=>{d[id]=1;q.push(id)});const by=Object.fromEntries(ed.def.nodes.map(n=>[n.id,n]));while(q.length){const n=by[q.shift()];if(!n)continue;(n.next||[]).forEach(c=>{if(!d[c]&&by[c]){d[c]=d[n.id]+1;q.push(c)}})}return d}
    function blankNode(protocol){return protocol==='shell'?{id:'',kind:'file',path:'/home/{{org.admin_user}}/notes.txt',body:'TODO: ใส่เบาะแสที่ชี้ไปยังจุดถัดไป\n',next:[]}:{id:'',kind:'file',path:'/robots.txt',body:'User-agent: *\nDisallow: /\n',next:[]}}
    function openEditor(def,isNew){ed.def=JSON.parse(JSON.stringify(def));delete ed.def.builtin;ed.def.nodes.forEach(n=>{n.next=n.next||[];if(n.body===undefined)n.body=''});ed.sel=ed.def.nodes[0]?.id||null;ed.isNew=isNew;ed.dirty=isNew;ed.report={errors:[],warnings:[]};$('rh-library').classList.add('hidden');$('rh-editor').classList.remove('hidden');$('rh-preview-card').classList.add('hidden');renderEditor();scheduleCheck(0);$('rh-editor').scrollIntoView({behavior:'smooth',block:'start'})}
    function closeEditor(){if(ed.dirty&&!window.__rhConfirmClose){window.__rhConfirmClose=true;$('ed-status').innerHTML='<span class="problems">ยังไม่ได้บันทึก กด "กลับ" อีกครั้งเพื่อทิ้งการแก้ไข</span>';return}window.__rhConfirmClose=false;ed.def=null;$('rh-editor').classList.add('hidden');$('rh-library').classList.remove('hidden');$('rh-preview-card').classList.add('hidden')}
    function newScenario(protocol){const node=blankNode(protocol);const def={id:'custom-'+Math.random().toString(16).slice(2,8),title:protocol==='shell'?'ฉาก SSH/Telnet ใหม่':'ฉาก Web ใหม่',description:'',protocol,entry:[],nodes:[]};ed.def=def;node.id=uniqueId(slug(node.path));def.nodes.push(node);def.entry.push(node.id);openEditor(def,true)}
    async function copyScenario(id){try{const d=await api('/api/rabbit-hole/scenario.json?id='+encodeURIComponent(id));d.id='custom-'+Math.random().toString(16).slice(2,8);d.title=d.title+' (สำเนา)';openEditor(d,true)}catch(e){$('rh-settings-result').innerHTML=`<span class="problems">${escapeHtml(e.message)}</span>`}}
    async function editScenario(id){try{openEditor(await api('/api/rabbit-hole/scenario.json?id='+encodeURIComponent(id)),false)}catch(e){$('rh-settings-result').innerHTML=`<span class="problems">${escapeHtml(e.message)}</span>`}}
    async function deleteScenario(id,button){if(button.dataset.confirm!=='1'){button.dataset.confirm='1';button.textContent='ยืนยันลบ';button.classList.add('danger-filled');return}try{await postScope('/api/rabbit-hole/scenario/delete',{id});setupFilled=false;await loadRabbit();renderRabbit()}catch(e){$('rh-settings-result').innerHTML=`<span class="problems">${escapeHtml(e.message)}</span>`}}
    function changed(full){ed.dirty=true;window.__rhConfirmClose=false;if(full)renderEditor();else{renderEdMap();renderEdStatus()}scheduleCheck()}
    function scheduleCheck(delay=500){clearTimeout(ed.timer);ed.timer=setTimeout(async()=>{if(!ed.def)return;try{ed.report=await postScope('/api/rabbit-hole/scenario/check',{definition:ed.def})}catch(e){ed.report={errors:[e.message],warnings:[]}}renderEdStatus()},delay)}
    function renderEditor(){const d=ed.def;$('rh-editor').innerHTML=`<div class="editor-bar card"><div class="editor-bar-main"><button type="button" class="text" id="ed-back">← กลับไปคลังฉาก</button><span class="pill ${d.protocol==='shell'?'warn':'info'}">${d.protocol==='shell'?'SSH/Telnet':'Web'}</span><span class="pill">${ed.isNew?'ฉากใหม่ยังไม่บันทึก':'รหัส '+escapeHtml(d.id)}</span></div><div class="split-actions"><button type="button" class="secondary" id="ed-preview">ดูสิ่งที่ผู้โจมตีเห็น</button><button type="button" id="ed-save">บันทึกฉาก</button></div></div>
      <div class="card"><div class="card-body editor-meta"><label>ชื่อฉาก<input id="ed-title" maxlength="120" value="${escapeHtml(d.title)}"></label><label>คำอธิบาย (ผู้โจมตีจะเดินอย่างไร)<textarea id="ed-desc" maxlength="600" rows="2">${escapeHtml(d.description||'')}</textarea></label></div></div>
      <div id="ed-status"></div>
      <div class="editor-grid"><div class="card"><div class="card-head"><h4 class="card-title">แผนผังเส้นทาง</h4><button type="button" class="tonal small" id="ed-add">+ เพิ่มจุด</button></div><div class="node-map editable" id="ed-map"></div><p class="data-note map-note">คลิกจุดเพื่อแก้ไข · ชั้นคำนวณจากเบาะแสอัตโนมัติ · ขอบเขียว = จุดเริ่มที่ผู้โจมตีเจอได้เอง</p></div><div class="card inspector" id="ed-inspector"></div></div>`;renderEdMap();renderInspector();renderEdStatus();
      $('ed-back').onclick=closeEditor;$('ed-save').onclick=saveScenario;$('ed-preview').onclick=previewDraft;$('ed-add').onclick=addNode;$('ed-title').oninput=e=>{d.title=e.target.value;changed()};$('ed-desc').oninput=e=>{d.description=e.target.value;changed()}}
    function renderEdMap(){const dep=depths();const nodes=ed.def.nodes.map(n=>({...n,depth:dep[n.id]||0,entry:ed.def.entry.includes(n.id)}));$('ed-map').innerHTML=nodeMap(nodes,true);const cards=[...$('ed-map').querySelectorAll('.node')];const order=[];const by={};nodes.forEach(x=>(by[x.depth||0]=by[x.depth||0]||[]).push(x));Object.keys(by).map(Number).sort((a,b)=>a-b).forEach(k=>by[k].forEach(x=>order.push(x.id)));cards.forEach((c,i)=>{c.tabIndex=0;c.dataset.id=order[i];c.classList.toggle('selected',order[i]===ed.sel);c.onclick=()=>{ed.sel=order[i];renderEdMap();renderInspector()};c.onkeydown=e=>{if(e.key==='Enter'){ed.sel=order[i];renderEdMap();renderInspector()}}})}
    function renderEdStatus(){const r=ed.report||{errors:[],warnings:[]};const el=$('ed-status');if(!el)return;el.innerHTML=`<div class="status-strip ${r.errors.length?'bad':r.warnings.length?'warn':'ok'}"><strong>${r.errors.length?`ต้องแก้ ${r.errors.length} จุดก่อนบันทึก`:r.warnings.length?`บันทึกได้ มีคำเตือน ${r.warnings.length} ข้อ`:'โครงสร้างถูกต้อง บันทึกได้'}</strong>${[...r.errors.map(x=>`<span class="err">✕ ${escapeHtml(x)}</span>`),...r.warnings.map(x=>`<span class="wrn">! ${escapeHtml(x)}</span>`)].join('')}</div>`;$('ed-save')&&($('ed-save').disabled=r.errors.length>0)}
    function addNode(){const n=blankNode(ed.def.protocol);n.path=ed.def.protocol==='shell'?'/opt/new-file.txt':'/new-file.txt';n.body='';n.id=uniqueId('n-'+Math.random().toString(16).slice(2,6));ed.def.nodes.push(n);ed.sel=n.id;changed(true)}
    function renderInspector(){const box=$('ed-inspector');const n=ed.def.nodes.find(x=>x.id===ed.sel);if(!n){box.innerHTML='<div class="card-body"><div class="empty">เลือกจุดในแผนผังเพื่อแก้ไข</div></div>';return}const web=ed.def.protocol==='web';const kinds=web?['file','listing','api','form','people_api']:['file','dir'];const others=ed.def.nodes.filter(x=>x.id!==n.id);const maxB=(rh.data.settings.limits||{}).max_branches||2;const hasBody=!['listing','dir'].includes(n.kind);const isPeople=n.kind==='people_api';
      box.innerHTML=`<div class="card-head"><h4 class="card-title">แก้ไขจุด</h4><button type="button" class="danger small" id="in-del">ลบจุดนี้</button></div><div class="card-body form-grid">
      <label>Path ที่ผู้โจมตีเห็น<input id="in-path" class="mono-input" value="${escapeHtml(n.path)}" placeholder="${web?'/backup/config.json':'/home/{{org.admin_user}}/notes.txt'}"></label>
      <div class="two-fields"><label>ชนิด<select id="in-kind">${kinds.map(k=>`<option value="${k}" ${k===n.kind?'selected':''}>${kindNames[k]}</option>`).join('')}</select></label>${web&&n.kind==='file'?`<label>ชนิดเนื้อหา<select id="in-ctype">${[['text/plain; charset=utf-8','ข้อความ'],['text/html; charset=utf-8','HTML'],['text/csv; charset=utf-8','CSV'],['application/json','JSON']].map(([v,l])=>`<option value="${v}" ${v===(n.content_type||'text/plain; charset=utf-8')?'selected':''}>${l}</option>`).join('')}</select></label>`:''}</div>
      <label class="check-row"><input type="checkbox" id="in-entry" ${ed.def.entry.includes(n.id)?'checked':''}> เป็นจุดเริ่ม (ผู้โจมตีเจอได้เองโดยไม่ต้องมีเบาะแส เช่น /robots.txt, /.env)</label>
      ${['api','people_api'].includes(n.kind)?`<label class="check-row"><input type="checkbox" id="in-key" ${n.requires_header&&n.requires_header['X-API-Key']?'checked':''}> ต้องส่ง X-API-Key ที่ได้จากเบาะแส ({{secret:token:api}})</label>`:''}
      <fieldset class="clue-box"><legend>ชี้ไปที่ (เบาะแสไปยังจุดถัดไป สูงสุด ${maxB} จุด)</legend>${others.length?others.map(o=>`<label class="check-row"><input type="checkbox" class="in-next" value="${escapeHtml(o.id)}" ${n.next.includes(o.id)?'checked':''} ${!n.next.includes(o.id)&&n.next.length>=maxB?'disabled':''}> <code>${escapeHtml(o.path)}</code></label>`).join(''):'<p class="data-note">ยังไม่มีจุดอื่น กด "+ เพิ่มจุด" ก่อน</p>'}</fieldset>
      ${n.kind==='listing'?`<label>ไฟล์ประกอบฉากในโฟลเดอร์ (คั่นด้วย , เปิดแล้วได้ 403)<input id="in-filler" class="mono-input" value="${escapeHtml((n.filler||[]).join(', '))}" placeholder="db_{{date:-1}}.sql.gz, site.tar.gz"></label><p class="data-note">รายการไฟล์สร้างให้อัตโนมัติจากจุดที่ "ชี้ไปที่" ซึ่งอยู่ในโฟลเดอร์นี้</p>`:''}
      ${n.kind==='dir'?'<p class="data-note">โฟลเดอร์ใน Shell แสดงไฟล์จากจุดที่ "ชี้ไปที่" ซึ่งอยู่ในโฟลเดอร์นี้</p>':''}
      ${isPeople?`<label>จำนวนคนในรายชื่อ (1–200)<input id="in-count" type="number" min="1" max="200" value="${escapeHtml(n.body||'10')}"></label><p class="data-note">เรียก path นี้ได้รายชื่อ และ path/รหัส (เช่น /1003) ได้รายละเอียดแต่ละคน</p>`:''}
      ${hasBody&&!isPeople?`<label>เนื้อหา<textarea id="in-body" class="mono-input" rows="10">${escapeHtml(n.body||'')}</textarea></label>
      ${n.next.length?`<div class="chip-row"><span>แทรกเบาะแสไปยัง:</span>${n.next.map(id=>{const t=ed.def.nodes.find(x=>x.id===id);return t?`<button type="button" class="chip-btn link" data-insert="{{node:${escapeHtml(id)}}}">${escapeHtml(t.path)}</button>`:''}).join('')}</div>`:''}
      <div class="chip-row"><span>แทรกค่าอัตโนมัติ:</span>${insertables.map(([l,v])=>`<button type="button" class="chip-btn" data-insert="${escapeHtml(v)}" title="${escapeHtml(v)}">${escapeHtml(l)}</button>`).join('')}</div>
      <p class="data-note">ค่าอัตโนมัติจะถูกแทนตอนผู้โจมตีเปิดไฟล์ ค่าสุ่มคงที่ใน Session เดียวกัน เปลี่ยน LABEL เป็นชื่ออะไรก็ได้เพื่อแยกค่า เช่น {{secret:password:db}}</p>`:''}
      </div>`;
      const set=(id,ev,fn)=>{const el=$(id);if(el)el.addEventListener(ev,fn)};
      set('in-path','input',e=>{n.path=e.target.value;changed()});
      set('in-kind','change',e=>{n.kind=e.target.value;if(n.kind==='people_api'&&!/^\d+$/.test(n.body||''))n.body='10';if(!['api','people_api'].includes(n.kind))delete n.requires_header;if(n.kind!=='file')delete n.content_type;if(n.kind!=='listing')delete n.filler;changed(true)});
      set('in-ctype','change',e=>{n.content_type=e.target.value;changed()});
      set('in-entry','change',e=>{ed.def.entry=e.target.checked?[...new Set([...ed.def.entry,n.id])]:ed.def.entry.filter(x=>x!==n.id);changed(true)});
      set('in-key','change',e=>{if(e.target.checked)n.requires_header={'X-API-Key':'{{secret:token:api}}'};else delete n.requires_header;changed()});
      set('in-filler','input',e=>{n.filler=e.target.value.split(',').map(x=>x.trim()).filter(Boolean);changed()});
      set('in-count','input',e=>{n.body=String(e.target.value);changed()});
      set('in-body','input',e=>{n.body=e.target.value;changed()});
      box.querySelectorAll('.in-next').forEach(c=>c.addEventListener('change',()=>{n.next=[...box.querySelectorAll('.in-next:checked')].map(x=>x.value);changed(true)}));
      box.querySelectorAll('[data-insert]').forEach(b=>b.addEventListener('click',()=>{const ta=$('in-body');if(!ta)return;const v=b.dataset.insert,s=ta.selectionStart??ta.value.length,e=ta.selectionEnd??s;ta.value=ta.value.slice(0,s)+v+ta.value.slice(e);ta.focus();const p=v.indexOf('LABEL');if(p>=0)ta.setSelectionRange(s+p,s+p+5);else ta.setSelectionRange(s+v.length,s+v.length);n.body=ta.value;changed()}));
      set('in-del','click',e=>{const btn=e.currentTarget;if(btn.dataset.confirm!=='1'){btn.dataset.confirm='1';btn.textContent='ยืนยันลบจุด';btn.classList.add('danger-filled');return}ed.def.nodes=ed.def.nodes.filter(x=>x.id!==n.id);ed.def.entry=ed.def.entry.filter(x=>x!==n.id);ed.def.nodes.forEach(x=>x.next=x.next.filter(y=>y!==n.id));ed.sel=ed.def.nodes[0]?.id||null;changed(true)})}
    async function saveScenario(){const btn=$('ed-save');btn.disabled=true;const title=ed.def.title;try{const r=await postScope('/api/rabbit-hole/scenario/save',{definition:ed.def});ed.dirty=false;ed.isNew=false;setupFilled=false;await loadRabbit();renderRabbit();closeEditor();$('rh-settings-result').innerHTML=`<span class="success">บันทึกฉาก "${escapeHtml(title)}" แล้ว${r.warnings&&r.warnings.length?' (มีคำเตือน '+r.warnings.length+' ข้อ)':''} · ติ๊ก "ใช้ฉากนี้" แล้วกดบันทึกการตั้งค่าเพื่อเปิดใช้</span>`}catch(e){ed.report={errors:[e.message],warnings:[]};renderEdStatus()}finally{if($('ed-save'))$('ed-save').disabled=(ed.report.errors||[]).length>0}}
    async function previewDraft(){$('rh-preview-card').classList.remove('hidden');$('rh-preview').innerHTML='<div class="empty">กำลังสร้างตัวอย่าง…</div>';try{const d=await postScope('/api/rabbit-hole/scenario/preview',{definition:ed.def});if(d.report&&d.report.errors.length){ed.report=d.report;renderEdStatus();$('rh-preview').innerHTML='<p class="problems">แก้ข้อผิดพลาดก่อนดูตัวอย่าง</p>';return}showPreview(ed.def.title,d)}catch(e){$('rh-preview').innerHTML=`<p class="error">${escapeHtml(e.message)}</p>`}}

    async function saveRabbit(event){event.preventDefault();const org={},limits={};document.querySelectorAll('[id^="rh-org-"]').forEach(i=>org[i.id.slice(7)]=i.value.trim());document.querySelectorAll('[id^="rh-limit-"]').forEach(i=>limits[i.id.slice(9)]=Number(i.value));limits.max_sessions=rh.data.settings.limits.max_sessions;const web=[...document.querySelectorAll('input[data-protocol="web"]:checked')].map(i=>i.value),shell=(document.querySelector('input[data-protocol="shell"]:checked')||{}).value||null;try{await postScope('/api/rabbit-hole/settings',{enabled:$('rh-enabled').checked,organization:org,limits,scenarios:{web,shell}});setupFilled=false;await loadRabbit();renderRabbit();$('rh-settings-result').textContent='บันทึกแล้ว Web decoy จะใช้ค่าใหม่กับคำขอถัดไป ส่วน SSH/Telnet ต้องดาวน์โหลดไฟล์ลวงไปติดตั้งใน Cowrie ใหม่'}catch(error){$('rh-settings-result').innerHTML=`<span class="problems">บันทึกไม่สำเร็จ: ${escapeHtml(error.message)}</span>`}}
    function showPreview(title,d){$('rh-preview-card').classList.remove('hidden');$('rh-preview-title').textContent='ตัวอย่างที่ผู้โจมตีเห็น: '+title;$('rh-preview').innerHTML=`<p class="data-note">${escapeHtml(d.note||'')}</p>`+d.resources.map(r=>`<div class="preview-item"><header><span class="pill deep">ชั้น ${r.depth}</span><code>${escapeHtml(r.path)}</code>${r.requires&&r.requires.length?`<span class="pill warn">ต้องมี ${escapeHtml(r.requires.join(', '))}</span>`:''}</header>${r.content?`<pre>${escapeHtml(r.content)}</pre>`:'<p class="data-note">โฟลเดอร์</p>'}</div>`).join('');$('rh-preview-card').scrollIntoView({behavior:'smooth',block:'start'})}
    async function previewScenario(id){$('rh-preview-card').classList.remove('hidden');$('rh-preview').innerHTML='<div class="empty">กำลังสร้างตัวอย่าง…</div>';try{const d=await api('/api/rabbit-hole/preview.json?scenario='+encodeURIComponent(id));const sc=(rh.data.scenarios||[]).find(s=>s.id===id);showPreview(sc?sc.title:id,d)}catch(error){$('rh-preview').innerHTML=`<p class="error">${escapeHtml(error.message)}</p>`}}
    function renderReportRabbit(r){$('report-rabbit-body').innerHTML=r?Object.entries(r.by_protocol).map(([k,b])=>`<tr><td>${protoName(k)}</td><td>${b.sessions}</td><td>${b.sessions_followed} (${pct(b.follow_rate)})</td><td>${b.average_depth??'-'} / ${b.max_depth}</td><td>${b.average_resources??'-'}</td><td>${secs(b.average_duration_seconds)}</td><td>${k==='web'?'—':secs(b.average_connection_seconds)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">ยังไม่มีข้อมูล Rabbit Hole ในช่วงเวลานี้</td></tr>':'<tr><td colspan="7" class="empty">ยังไม่ได้ตั้งค่า Rabbit Hole</td></tr>'}
    document.querySelectorAll('[data-rh-tab]').forEach(b=>b.addEventListener('click',()=>selectRhTab(b.dataset.rhTab)));
    ['rh-filter-protocol','rh-filter-depth','rh-filter-followed'].forEach(id=>$(id).addEventListener('change',renderWindows));
    $('rh-windows-body').addEventListener('click',e=>{const row=e.target.closest('tr[data-id]');if(row)showTrail(row.dataset.id)});
    $('rh-windows-body').addEventListener('keydown',e=>{const row=e.target.closest('tr[data-id]');if(row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();showTrail(row.dataset.id)}});
    $('rh-settings-form').addEventListener('submit',saveRabbit);
    $('rh-scenarios').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.classList.contains('rh-preview'))previewScenario(b.dataset.id);else if(b.classList.contains('rh-copy'))copyScenario(b.dataset.id);else if(b.classList.contains('rh-edit'))editScenario(b.dataset.id);else if(b.classList.contains('rh-delete'))deleteScenario(b.dataset.id,b)});
    $('rh-new-web').addEventListener('click',()=>newScenario('web'));$('rh-new-shell').addEventListener('click',()=>newScenario('shell'));
    $('rh-preview-close').addEventListener('click',()=>$('rh-preview-card').classList.add('hidden'));
    $('overview-rabbit-open').addEventListener('click',()=>{switchView('rabbit');selectRhTab('sessions')});

    /* ---------- Deploy หน้าเว็บ (SNARE) ---------- */
    const dp={status:null,job:null,poll:null,preview:null,target:null};
    const dpBytes=n=>n>1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
    async function loadDeploy(){if(state.user?.role!=='master_admin')return;try{dp.status=await api('/api/web-deploy/status.json');$('dp-error').textContent='';$('dp-missing').classList.add('hidden');$('dp-body').classList.remove('hidden');renderDeploy();if(dp.status.job&&!dp.poll)watchJob(dp.status.job.id)}catch(e){if(e.status===404||e.message==='deploy_agent_not_configured'){$('dp-missing').classList.remove('hidden');$('dp-body').classList.add('hidden');$('dp-mode').textContent='ยังไม่ได้เชื่อม';$('dp-mode').className='pill warn'}else{$('dp-error').textContent=e.message==='deploy_agent_unreachable'?'ติดต่อ Deploy agent บนเครื่อง Honeypot ไม่ได้ ตรวจว่า service ทำงานและ firewall เปิดพอร์ตให้ Defender':'โหลดสถานะไม่สำเร็จ: '+e.message}}}
    function renderDeploy(){const s=dp.status;$('dp-mode').textContent=s.dry_run?'โหมดทดลอง (ไม่เรียก Docker)':'เชื่อมเครื่อง Honeypot แล้ว';$('dp-mode').className='pill '+(s.dry_run?'warn':'ok');const active=s.versions.find(v=>v.active);$('dp-active').textContent=s.active;$('dp-active-url').textContent=active?'clone จาก '+active.url:(s.active==='demo'?'หน้าเริ่มต้นของ SNARE':'-');$('dp-health').innerHTML=`<span class="pill ${s.healthy?'ok':'bad'}">${s.healthy?'ตอบปกติ':'ไม่ตอบ'}</span>`;$('dp-targets').innerHTML=s.allowed_targets.map(t=>`<option value="${escapeHtml(/^https?:/.test(t)?t:'http://'+t+'/')}">`).join('');$('dp-allowed').innerHTML='clone ได้เฉพาะ host ที่อนุญาตในเครื่อง Honeypot: '+s.allowed_targets.map(t=>`<code>${escapeHtml(t)}</code>`).join(' ');$('dp-versions').innerHTML=s.versions.map(v=>`<tr><td class="mono">${escapeHtml(v.version)}${v.active?' <span class="pill ok">ใช้อยู่</span>':''}</td><td class="mono">${escapeHtml(v.url)}</td><td>${when(v.created)}</td><td>${v.pages}<small>${dpBytes(v.bytes)}</small></td><td>${v.findings.length?`<span class="pill warn">${v.findings.length} จุด</span>`:'<span class="pill ok">ไม่พบ</span>'}</td><td><div class="split-actions dp-actions"><button type="button" class="text small dp-view" data-v="${escapeHtml(v.version)}">ดูตัวอย่าง</button>${v.active?'':`<button type="button" class="small dp-go" data-v="${escapeHtml(v.version)}">Deploy</button>`}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">ยังไม่มีเวอร์ชัน วางลิงก์ด้านบนแล้วกด Clone</td></tr>';$('dp-clone-btn').disabled=!!(s.job)}
    function showJob(job){dp.job=job;$('dp-job').classList.remove('hidden');$('dp-job-title').textContent=job.kind==='clone'?'Clone เว็บ':'Deploy เวอร์ชัน';const st={queued:['รอคิว','info'],running:['กำลังทำงาน','warn'],succeeded:['สำเร็จ','ok'],failed:['ไม่สำเร็จ','bad']}[job.status]||[job.status,''];$('dp-job-status').textContent=st[0];$('dp-job-status').className='pill '+st[1];const log=$('dp-job-log');log.textContent=job.log.join('\n')+(job.error?'\n'+job.error:'');log.scrollTop=log.scrollHeight}
    function watchJob(id){clearInterval(dp.poll);$('dp-clone-btn').disabled=true;dp.poll=setInterval(async()=>{try{const job=await api('/api/web-deploy/job.json?id='+encodeURIComponent(id));showJob(job);if(!['queued','running'].includes(job.status)){clearInterval(dp.poll);dp.poll=null;await loadDeploy();if(job.status==='succeeded'&&job.kind==='clone')previewVersion(job.result.version)}}catch(e){clearInterval(dp.poll);dp.poll=null;$('dp-error').textContent=e.message}},1200)}
    async function cloneSite(e){e.preventDefault();$('dp-error').textContent='';try{const job=await postScope('/api/web-deploy/clone',{url:$('dp-url').value.trim(),depth:Number($('dp-depth').value)});showJob(job);watchJob(job.id)}catch(err){$('dp-error').textContent={target_not_allowed:'host นี้ไม่อยู่ในรายการที่อนุญาตให้ clone',url_must_be_http_or_https:'ลิงก์ต้องขึ้นต้นด้วย http:// หรือ https://',job_running:'มีงานที่กำลังทำอยู่ รอให้เสร็จก่อน',url_must_not_contain_credentials:'ห้ามใส่ชื่อผู้ใช้หรือรหัสผ่านในลิงก์'}[err.message]||err.message}}
    async function previewVersion(version,url){dp.preview=version;$('dp-preview-card').classList.remove('hidden');$('dp-preview-title').textContent='ตัวอย่าง: '+version;const v=(dp.status?.versions||[]).find(x=>x.version===version);$('dp-findings').innerHTML=v&&v.findings.length?`<div class="status-strip warn"><strong>พบ ${v.findings.length} จุดที่ควรตรวจก่อน Deploy</strong>${v.findings.slice(0,8).map(f=>`<span class="wrn">! ${escapeHtml(f.label)} ใน ${escapeHtml(f.url)}${f.sample?' — '+escapeHtml(f.sample):''}</span>`).join('')}</div>`:'<div class="status-strip ok"><strong>ไม่พบรหัสผ่าน key หรือ IP ภายในในหน้าที่ clone มา</strong></div>';try{if(!url){const pages=(await api('/api/web-deploy/pages.json?version='+encodeURIComponent(version))).items;$('dp-page').innerHTML=pages.map(p=>`<option>${escapeHtml(p)}</option>`).join('');url=pages.includes('/index.html')?'/index.html':pages[0]}$('dp-page').value=url;const page=await api('/api/web-deploy/page.json?'+new URLSearchParams({version,url}));$('dp-frame').srcdoc=page.content_type.includes('html')?page.content:`<pre>${escapeHtml(page.content)}</pre>`}catch(e){$('dp-frame').srcdoc=`<p>${escapeHtml(e.message)}</p>`}$('dp-preview-card').scrollIntoView({behavior:'smooth',block:'start'})}
    function openDeploy(version){dp.target=version;const v=(dp.status?.versions||[]).find(x=>x.version===version);$('deploy-form').reset();$('deploy-error').textContent='';$('deploy-version').textContent=version;$('deploy-findings').textContent=v&&v.findings.length?`เวอร์ชันนี้มีคำเตือน ${v.findings.length} จุด กด "ดูตัวอย่าง" เพื่อตรวจก่อน`:'';$('deploy-totp-row').classList.toggle('hidden',!state.user.totp_enabled);$('deploy-totp').required=!!state.user.totp_enabled;$('deploy-dialog').showModal()}
    async function submitDeploy(e){e.preventDefault();$('deploy-error').textContent='';try{const job=await postScope('/api/web-deploy/activate',{version:dp.target,password:$('deploy-password').value,totp:$('deploy-totp').value,confirmation:$('deploy-confirm').value});$('deploy-dialog').close();showJob(job);watchJob(job.id);$('dp-job').scrollIntoView({behavior:'smooth',block:'center'})}catch(err){$('deploy-error').textContent={deploy_confirmation_failed:'รหัสผ่าน รหัส TOTP หรือคำยืนยันไม่ถูกต้อง',rate_limited:'ลองใหม่ภายหลัง: กรอกผิดหลายครั้ง',job_running:'มีงานที่กำลังทำอยู่ รอให้เสร็จก่อน'}[err.message]||err.message}}
    $('dp-clone-form').addEventListener('submit',cloneSite);
    $('dp-versions').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.classList.contains('dp-view'))previewVersion(b.dataset.v);if(b.classList.contains('dp-go'))openDeploy(b.dataset.v)});
    $('dp-page').addEventListener('change',()=>previewVersion(dp.preview,$('dp-page').value));
    $('dp-preview-close').addEventListener('click',()=>$('dp-preview-card').classList.add('hidden'));
    $('deploy-form').addEventListener('submit',submitDeploy);
    $('deploy-cancel').addEventListener('click',()=>$('deploy-dialog').close());
    document.querySelector('[data-view="deploy"]').addEventListener('click',loadDeploy);

